  ctx.fillStyle = '#e8eef4'; ctx.fillRect(0, H * 0.17, W, 2.6 * u); ctx.fillStyle = '#ffffff'; ctx.fillRect(W * 0.1, H * 0.175, W * 0.3, 0.8 * u);
