  ctx.strokeStyle = '#e0d4c2'; ctx.lineWidth = 0.6 * u; for (let k = 0; k < 8; k++) { ctx.beginPath(); ctx.moveTo(W * (0.05 + k * 0.13), H * 0.81); ctx.quadraticCurveTo(W * (0.1 + k * 0.13), H * 0.9, W * (0.06 + k * 0.13), H); ctx.stroke(); }
