    school([[fx + fw * 0.36, fy + fh + 10], [fx + fw * 0.24, fy + fh * 0.78], [fx + fw * 0.1, fy + fh * 0.7], [fx - 10, fy + fh * 0.78]], 5, 2, 14, 9);
