    const A = 14 * u, B = 8.2 * u;
    ctx.fillStyle = 'rgba(60,40,20,.35)'; ctx.beginPath(); ctx.ellipse(1 * u, 1.2 * u, A, B, 0, 0, Math.PI * 2); ctx.fill();
