  for (let k = 0; k < 90; k++) { const a = R() * Math.PI * 2, r = Math.sqrt(R()) * 10.8 * u; berries.push([bx + Math.cos(a) * r, by + Math.sin(a) * r]); }
  berries.sort((p, q) => p[1] - q[1]);
