    for (let j = 0; j < 9; j++) for (let i = 0; i < 18; i++) paw(Math.round(fx + 5 + i * 11 + (j % 2) * 5.5), Math.round(fy + 6 + j * 12), C.blue2);
    // three rows of dogs, staggered, facing each way, running and sitting
    const S = 34, dogs = [];
