    R(fx, fy, fw, fh, C.wood);
    for (let j = fy; j < fy + fh; j++) {
      if ((j - fy) % 13 === 12) { R(fx, j, fw, 1, C.wood3); continue; }
      for (let i = fx; i < fx + fw; i++) { const g = Math.sin(i * 0.11 + j * 0.9 + Math.sin(i * 0.031 + j) * 3); if (g > 0.86) P(i, j, C.wood2); }
    }
