    ctx.fillStyle = '#a8a292'; for (let k = 0; k < 4; k++) { const t = 0.55 + r() * 0.4, x = cx - w / 2 + w * t; ctx.beginPath(); ctx.moveTo(x, pts[Math.round(t * 40)][1] + 1 * u); ctx.lineTo(x + 1.6 * u, base); ctx.lineTo(x - 1.2 * u, base); ctx.fill(); }
