    c.fillStyle = '#f0e4c6'; c.beginPath(); c.moveTo(w * 0.2, h); c.quadraticCurveTo(w * 0.3, Y(0.4), w * 0.85, Y(0.2)); c.quadraticCurveTo(w * 0.55, Y(0.5), w * 0.8, h); c.fill();
