    c.fillStyle = '#e8402e'; c.beginPath(); c.arc(w * 0.32, Y(0.72), w * 0.06, 0, Math.PI * 2); c.fill(); c.fillStyle = '#f2c030'; c.beginPath(); c.arc(w * 0.7, Y(0.62), w * 0.06, 0, Math.PI * 2); c.fill();
