  const C = { navy: '#1c2742', navy2: '#24345a', dark: '#111827', cu1: '#f6c492', cu2: '#d8874c', cu3: '#a65a2e', cu4: '#62301a', white: '#f7f3ea', grey: '#bfc0c4', coffee: '#3a2216', crema: '#a8743e', pink: '#ec8eaa', rose: '#b84a6a', green: '#94c46e', green2: '#5a8a4a' };
