    const P = (a, b, col) => { x.fillStyle = col; x.fillRect(Math.floor(a), Math.floor(b), 1, 1); };
    const R = (a, b, w, h, col) => { x.fillStyle = col; x.fillRect(Math.floor(a), Math.floor(b), w, h); };
