    ctx.fillStyle = '#6a5a86'; for (let k = 0; k < 9; k++) { const t = k / 8, y = H * (0.5 + t * 0.4), x1 = W * (0.66 + t * 0.26); ctx.fillRect(x1 - 12 * u - ((k * 5) % 4) * u, y, 10 * u, 1.3 * u); }
