  const right = [[1, 0.2], [0.93, 0.22], [0.86, 0.27], [0.8, 0.33], [0.74, 0.39], [0.68, 0.44], [0.64, 0.46], [0.66, 0.48], [0.72, 0.55], [0.8, 0.66], [0.88, 0.8], [0.94, 1], [1, 1]];
