    ctx.fillStyle = '#54426a'; for (const [a, b, w, h] of [[0.91, 0.26, 2, 50], [0.84, 0.32, 2, 40], [0.77, 0.4, 1.6, 26], [0.98, 0.24, 2, 60]]) ctx.fillRect(W * a, H * b, w * u, h * u);
