  ctx.fillStyle = '#d4d8ea'; ctx.beginPath(); ctx.moveTo(bx + 2 * u, by + 0.6 * u); ctx.lineTo(bx + 12 * u, by + 4.6 * u); ctx.lineTo(bx + 9 * u, by + 5 * u); ctx.lineTo(bx + 1 * u, by + 1.4 * u); ctx.fill();
