  const ridge = (pts, col) => { ctx.fillStyle = col; ctx.beginPath(); ctx.moveTo(0, H); pts.forEach(([a, b]) => ctx.lineTo(a * W, b * H)); ctx.lineTo(W, H); ctx.closePath(); ctx.fill(); };
