  const sky = ctx.createLinearGradient(0, 0, 0, vy); sky.addColorStop(0, '#86b2da'); sky.addColorStop(0.45, '#c8d0e0'); sky.addColorStop(0.8, '#f4d6b8'); sky.addColorStop(1, '#f8e0b0');
